import { useState } from "react";

const LOGO_IMG = "data:image/png;base64,";
const BANNER_IMG = "data:image/png;base64,";

/* ── GLOBAL STYLES ─────────────────────────────────────────── */
const G = `
@import url('https://fonts.googleapis.com/css2?family=Frank+Ruhl+Libre:wght@300;400;500;700;900&family=Heebo:wght@300;400;500;600;700&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Heebo', sans-serif;
  direction: rtl;
  background: #FAF6EE;
  color: #1C1C1C;
  line-height: 1.6;
}

:root {
  --gold: #B18931;
  --gold-light: #CAB482;
  --gold-dark: #8B5F06;
  --gold-bg: #FDF9ED;
  --deep-blue: #060F20;
  --mid-blue: #0B1636;
  --cream: #FEFAF1;
  --cream-dark: #F5EDD8;
  --text: #1C1C1C;
  --text-muted: #6B6B6B;
  --border: #D9C89A;
  --white: #ffffff;
  --teal: #1D8DA1;
  --teal-dark: #0E6368;
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes pulse-gold {
  0%, 100% { box-shadow: 0 0 0 0 rgba(201,168,76,0.4); }
  50%       { box-shadow: 0 0 0 10px rgba(201,168,76,0); }
}

.fade-up { animation: fadeUp 0.6s ease both; }
.fade-up-2 { animation: fadeUp 0.6s 0.15s ease both; }
.fade-up-3 { animation: fadeUp 0.6s 0.3s ease both; }
.fade-up-4 { animation: fadeUp 0.6s 0.45s ease both; }

.gold-btn {
  background: linear-gradient(135deg, var(--gold) 0%, var(--gold-light) 50%, var(--gold) 100%);
  background-size: 200% auto;
  color: var(--deep-blue);
  font-family: 'Frank Ruhl Libre', serif;
  font-weight: 700;
  font-size: 1.1rem;
  border: none;
  cursor: pointer;
  padding: 0.85rem 2.2rem;
  border-radius: 4px;
  letter-spacing: 0.03em;
  transition: background-position 0.4s, transform 0.2s, box-shadow 0.2s;
  animation: pulse-gold 2.5s ease infinite;
}
.gold-btn:hover {
  background-position: right center;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(201,168,76,0.45);
}

.outline-btn {
  background: transparent;
  color: var(--gold);
  border: 1.5px solid var(--gold);
  font-family: 'Heebo', sans-serif;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  padding: 0.6rem 1.5rem;
  border-radius: 4px;
  transition: all 0.2s;
}
.outline-btn:hover {
  background: var(--gold);
  color: var(--deep-blue);
}

.section-label {
  font-family: 'Heebo', sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 0.5rem;
}
.section-title {
  font-family: 'Frank Ruhl Libre', serif;
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 700;
  color: var(--deep-blue);
  line-height: 1.25;
}

.gold-divider {
  width: 60px;
  height: 3px;
  background: linear-gradient(90deg, var(--gold), var(--gold-light));
  border-radius: 2px;
  margin: 1rem auto;
}
`;

/* ── NAV ────────────────────────────────────────────────────── */
